use std::cmp::Ordering;
use std::hash::{Hash, Hasher};
use std::ops::Range;
use std::path::{Path, PathBuf};

use kode_acquisition::Language;

use crate::extraction::diagnostic::ExtractionDiagnostic;
use kode_common::hash::Fnv1aHasher;

/// Stable, deterministic identifier for an extracted entity.
///
/// Generated by hashing (language, kind, file path, name, byte offset),
/// guaranteeing uniqueness and reproducibility regardless of traversal order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct EntityId(u64);

impl EntityId {
    pub fn from_location(
        language: &Language,
        kind: &str,
        path: &Path,
        name: &str,
        byte_offset: usize,
    ) -> Self {
        let mut hasher = Fnv1aHasher::new();
        language.hash(&mut hasher);
        kind.hash(&mut hasher);
        path.hash(&mut hasher);
        name.hash(&mut hasher);
        byte_offset.hash(&mut hasher);
        Self(hasher.finish())
    }

    pub fn as_u64(&self) -> u64 {
        self.0
    }

    /// Create an `EntityId` from a raw u64 value.
    ///
    /// # Safety
    ///
    /// The caller must ensure the value was produced by
    /// [`EntityId::from_location`] or [`EntityId::as_u64`].
    /// This constructor does not recompute the hash.
    pub fn from_u64(value: u64) -> Self {
        Self(value)
    }
}

impl Ord for EntityId {
    fn cmp(&self, other: &Self) -> Ordering {
        self.0.cmp(&other.0)
    }
}

impl PartialOrd for EntityId {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl std::fmt::Display for EntityId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{:016x}", self.0)
    }
}

/// Source location evidence for an extracted entity.
///
/// Every entity must have evidence tracing it back to the source code.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Evidence {
    source_file: PathBuf,
    node_kind: String,
    byte_range: Range<usize>,
    start_line: usize,
    start_column: usize,
    end_line: usize,
    end_column: usize,
    language: Language,
}

impl Evidence {
    #[allow(clippy::too_many_arguments)]
    pub fn new(
        source_file: PathBuf,
        node_kind: impl Into<String>,
        byte_range: Range<usize>,
        start_line: usize,
        start_column: usize,
        end_line: usize,
        end_column: usize,
        language: Language,
    ) -> Self {
        Self {
            source_file,
            node_kind: node_kind.into(),
            byte_range,
            start_line,
            start_column,
            end_line,
            end_column,
            language,
        }
    }

    pub fn source_file(&self) -> &Path {
        &self.source_file
    }

    pub fn node_kind(&self) -> &str {
        &self.node_kind
    }

    pub fn byte_range(&self) -> &Range<usize> {
        &self.byte_range
    }

    pub fn start_line(&self) -> usize {
        self.start_line
    }

    pub fn start_column(&self) -> usize {
        self.start_column
    }

    pub fn end_line(&self) -> usize {
        self.end_line
    }

    pub fn end_column(&self) -> usize {
        self.end_column
    }

    pub fn language(&self) -> &Language {
        &self.language
    }
}

/// Visibility level for Rust items.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Visibility {
    Public,
    Crate,
    Super,
    Restricted(String),
    Private,
}

impl std::fmt::Display for Visibility {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Visibility::Public => write!(f, "public"),
            Visibility::Crate => write!(f, "crate"),
            Visibility::Super => write!(f, "super"),
            Visibility::Private => write!(f, "private"),
            Visibility::Restricted(s) => write!(f, "restricted({s})"),
        }
    }
}

impl std::str::FromStr for Visibility {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "public" => Ok(Visibility::Public),
            "crate" => Ok(Visibility::Crate),
            "super" => Ok(Visibility::Super),
            "private" => Ok(Visibility::Private),
            r if r.starts_with("restricted(") && r.ends_with(')') => {
                Ok(Visibility::Restricted(r[11..r.len() - 1].to_string()))
            }
            other => Err(format!("unknown visibility: {other}")),
        }
    }
}

