/// Discriminated entity type wrapping all fact variants.
#[derive(Debug, Clone)]
pub enum Entity {
    Module(ModuleFact),
    Function(FunctionFact),
    Struct(StructFact),
    Enum(EnumFact),
    Trait(TraitFact),
    ImplBlock(ImplBlockFact),
    TypeAlias(TypeAliasFact),
    Constant(ConstantFact),
    Static(StaticFact),
    Import(ImportFact),
    Export(ExportFact),
}

// ---------------------------------------------------------------------------
// RepositoryFacts
// ---------------------------------------------------------------------------

/// Immutable, complete extracted semantic model for a repository.
///
/// Owns all extracted entities with deterministic ordering and
/// evidence attached to every entity.
#[derive(Debug, Clone)]
pub struct RepositoryFacts {
    modules: Vec<ModuleFact>,
    functions: Vec<FunctionFact>,
    structs: Vec<StructFact>,
    enums: Vec<EnumFact>,
    traits: Vec<TraitFact>,
    impl_blocks: Vec<ImplBlockFact>,
    type_aliases: Vec<TypeAliasFact>,
    constants: Vec<ConstantFact>,
    statics: Vec<StaticFact>,
    imports: Vec<ImportFact>,
    exports: Vec<ExportFact>,
    diagnostics: Vec<ExtractionDiagnostic>,
}

impl RepositoryFacts {
    /// Construct from a flat vector of entities and diagnostics.
    ///
    /// Entities are partitioned by type and sorted by [`EntityId`]
    /// for deterministic ordering independent of traversal order.
    pub fn from_entities(entities: Vec<Entity>, diagnostics: Vec<ExtractionDiagnostic>) -> Self {
        let mut modules = Vec::new();
        let mut functions = Vec::new();
        let mut structs = Vec::new();
        let mut enums = Vec::new();
        let mut traits = Vec::new();
        let mut impl_blocks = Vec::new();
        let mut type_aliases = Vec::new();
        let mut constants = Vec::new();
        let mut statics = Vec::new();
        let mut imports = Vec::new();
        let mut exports = Vec::new();

        for entity in entities {
            match entity {
                Entity::Module(e) => modules.push(e),
                Entity::Function(e) => functions.push(e),
                Entity::Struct(e) => structs.push(e),
                Entity::Enum(e) => enums.push(e),
                Entity::Trait(e) => traits.push(e),
                Entity::ImplBlock(e) => impl_blocks.push(e),
                Entity::TypeAlias(e) => type_aliases.push(e),
                Entity::Constant(e) => constants.push(e),
                Entity::Static(e) => statics.push(e),
                Entity::Import(e) => imports.push(e),
                Entity::Export(e) => exports.push(e),
            }
        }

        let sort_by_id = |a: &EntityId, b: &EntityId| a.cmp(b);

        modules.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        functions.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        structs.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        enums.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        traits.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        impl_blocks.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        type_aliases.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        constants.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        statics.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        imports.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        exports.sort_by(|a, b| sort_by_id(a.id(), b.id()));

        Self {
            modules,
            functions,
            structs,
            enums,
            traits,
            impl_blocks,
            type_aliases,
            constants,
            statics,
            imports,
            exports,
            diagnostics,
        }
    }

    /// Create an empty `RepositoryFacts`.
    pub fn empty() -> Self {
        Self {
            modules: Vec::new(),
            functions: Vec::new(),
            structs: Vec::new(),
            enums: Vec::new(),
            traits: Vec::new(),
            impl_blocks: Vec::new(),
            type_aliases: Vec::new(),
            constants: Vec::new(),
            statics: Vec::new(),
            imports: Vec::new(),
            exports: Vec::new(),
            diagnostics: Vec::new(),
        }
    }

    // ------------------------------------------------------------------
    // Accessors
    // ------------------------------------------------------------------

    pub fn modules(&self) -> &[ModuleFact] {
        &self.modules
    }
    pub fn functions(&self) -> &[FunctionFact] {
        &self.functions
    }
    pub fn structs(&self) -> &[StructFact] {
        &self.structs
    }
    pub fn enums(&self) -> &[EnumFact] {
        &self.enums
    }
    pub fn traits(&self) -> &[TraitFact] {
        &self.traits
    }
    pub fn impl_blocks(&self) -> &[ImplBlockFact] {
        &self.impl_blocks
    }
    pub fn type_aliases(&self) -> &[TypeAliasFact] {
        &self.type_aliases
    }
    pub fn constants(&self) -> &[ConstantFact] {
        &self.constants
    }
    pub fn statics(&self) -> &[StaticFact] {
        &self.statics
    }
    pub fn imports(&self) -> &[ImportFact] {
        &self.imports
    }
    pub fn exports(&self) -> &[ExportFact] {
        &self.exports
    }
    pub fn diagnostics(&self) -> &[ExtractionDiagnostic] {
        &self.diagnostics
    }

    pub fn is_empty(&self) -> bool {
        self.modules.is_empty()
            && self.functions.is_empty()
            && self.structs.is_empty()
            && self.enums.is_empty()
            && self.traits.is_empty()
            && self.impl_blocks.is_empty()
            && self.type_aliases.is_empty()
            && self.constants.is_empty()
            && self.statics.is_empty()
            && self.imports.is_empty()
            && self.exports.is_empty()
    }

    /// Total count of all entities (excluding diagnostics).
    pub fn entity_count(&self) -> usize {
        self.modules.len()
            + self.functions.len()
            + self.structs.len()
            + self.enums.len()
            + self.traits.len()
            + self.impl_blocks.len()
            + self.type_aliases.len()
            + self.constants.len()
            + self.statics.len()
            + self.imports.len()
            + self.exports.len()
    }

    /// Merge another `RepositoryFacts` into this one.
    ///
    /// All entities are merged and re-sorted. Diagnostics are appended.
    pub fn merge(&mut self, other: Self) {
        self.modules.extend(other.modules);
        self.functions.extend(other.functions);
        self.structs.extend(other.structs);
        self.enums.extend(other.enums);
        self.traits.extend(other.traits);
        self.impl_blocks.extend(other.impl_blocks);
        self.type_aliases.extend(other.type_aliases);
        self.constants.extend(other.constants);
        self.statics.extend(other.statics);
        self.imports.extend(other.imports);
        self.exports.extend(other.exports);
        self.diagnostics.extend(other.diagnostics);

        let sort_by_id = |a: &EntityId, b: &EntityId| a.cmp(b);
        self.modules.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.functions.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.structs.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.enums.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.traits.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.impl_blocks.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.type_aliases.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.constants.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.statics.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.imports.sort_by(|a, b| sort_by_id(a.id(), b.id()));
        self.exports.sort_by(|a, b| sort_by_id(a.id(), b.id()));
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sample_evidence(path: &str) -> Evidence {
        Evidence::new(
            PathBuf::from(path),
            "test_node",
            0..10,
            1,
            1,
            1,
            10,
            Language::Rust,
        )
    }

    #[test]
    fn entity_id_deterministic() {
        let path = Path::new("src/lib.rs");
        let id1 = EntityId::from_location(&Language::Rust, "function", path, "foo", 42);
        let id2 = EntityId::from_location(&Language::Rust, "function", path, "foo", 42);
        assert_eq!(id1, id2);
    }

    #[test]
    fn entity_id_differs_for_different_names() {
        let path = Path::new("src/lib.rs");
        let id1 = EntityId::from_location(&Language::Rust, "function", path, "foo", 42);
        let id2 = EntityId::from_location(&Language::Rust, "function", path, "bar", 42);
        assert_ne!(id1, id2);
    }

    #[test]
    fn repository_facts_empty() {
        let facts = RepositoryFacts::empty();
        assert!(facts.is_empty());
        assert_eq!(facts.entity_count(), 0);
    }

    #[test]
    fn repository_facts_partitions_entities() {
        let ev = sample_evidence("test.rs");
        let func = FunctionFact::new(
            EntityId::from_location(&Language::Rust, "function", Path::new("test.rs"), "foo", 0),
            "foo",
            Visibility::Public,
            None,
            Vec::new(),
            false,
            false,
            false,
            None,
            None,
            None,
            ev,
        );

        let entities = vec![Entity::Function(func)];
        let facts = RepositoryFacts::from_entities(entities, Vec::new());

        assert_eq!(facts.functions().len(), 1);
        assert_eq!(facts.functions()[0].name(), "foo");
        assert!(facts.modules().is_empty());
    }

    #[test]
    fn repository_facts_deterministic_ordering() {
        let ev1 = sample_evidence("test.rs");
        let ev2 = sample_evidence("test.rs");
        let ev3 = sample_evidence("test.rs");

        let f1 = FunctionFact::new(
            EntityId::from_location(&Language::Rust, "function", Path::new("test.rs"), "bbb", 0),
            "bbb",
            Visibility::Public,
            None,
            Vec::new(),
            false,
            false,
            false,
            None,
            None,
            None,
            ev1,
        );
        let f2 = FunctionFact::new(
            EntityId::from_location(&Language::Rust, "function", Path::new("test.rs"), "aaa", 0),
            "aaa",
            Visibility::Public,
            None,
            Vec::new(),
            false,
            false,
            false,
            None,
            None,
            None,
            ev2,
        );
        let f3 = FunctionFact::new(
            EntityId::from_location(&Language::Rust, "function", Path::new("test.rs"), "ccc", 0),
            "ccc",
            Visibility::Public,
            None,
            Vec::new(),
            false,
            false,
            false,
            None,
            None,
            None,
            ev3,
        );

        // Verify same input produces same order
        let facts1 = RepositoryFacts::from_entities(
            vec![
                Entity::Function(f1.clone()),
                Entity::Function(f2.clone()),
                Entity::Function(f3.clone()),
            ],
            Vec::new(),
        );
        let facts2 = RepositoryFacts::from_entities(
            vec![
                Entity::Function(f3),
                Entity::Function(f1),
                Entity::Function(f2),
            ],
            Vec::new(),
        );

        let names1: Vec<&str> = facts1.functions().iter().map(|f| f.name()).collect();
        let names2: Vec<&str> = facts2.functions().iter().map(|f| f.name()).collect();
        assert_eq!(
            names1, names2,
            "ordering must be deterministic regardless of input order"
        );
        assert_eq!(facts1.functions().len(), 3);
    }

    #[test]
    fn evidence_roundtrip() {
        let ev = Evidence::new(
            PathBuf::from("src/main.rs"),
            "function_item",
            42..100,
            3,
            5,
            7,
            20,
            Language::Rust,
        );
        assert_eq!(ev.source_file(), Path::new("src/main.rs"));
        assert_eq!(ev.node_kind(), "function_item");
        assert_eq!(*ev.byte_range(), 42..100);
        assert_eq!(ev.start_line(), 3);
        assert_eq!(ev.start_column(), 5);
        assert_eq!(ev.end_line(), 7);
        assert_eq!(ev.end_column(), 20);
        assert_eq!(ev.language(), &Language::Rust);
    }

    #[test]
    fn merge_facts() {
        let ev = sample_evidence("a.rs");
        let f1 = FunctionFact::new(
            EntityId::from_location(&Language::Rust, "function", Path::new("a.rs"), "a", 0),
            "a",
            Visibility::Public,
            None,
            Vec::new(),
            false,
            false,
            false,
            None,
            None,
            None,
            ev,
        );
        let ev2 = sample_evidence("b.rs");
        let f2 = FunctionFact::new(
            EntityId::from_location(&Language::Rust, "function", Path::new("b.rs"), "b", 0),
            "b",
            Visibility::Public,
            None,
            Vec::new(),
            false,
            false,
            false,
            None,
            None,
            None,
            ev2,
        );

        let mut facts1 = RepositoryFacts::from_entities(vec![Entity::Function(f1)], Vec::new());
        let facts2 = RepositoryFacts::from_entities(vec![Entity::Function(f2)], Vec::new());
        facts1.merge(facts2);

        assert_eq!(facts1.functions().len(), 2);
    }

    #[test]
    fn entity_id_display() {
        let id = EntityId(0xdeadbeef);
        assert_eq!(format!("{id}"), "00000000deadbeef");
    }
}
